expression:
StringIO.new(
                <<~HCL
                    module "vpc" {
                      source = "terraform-aws-modules/vpc/aws"
                      version = "2.0.0"
                      region = var.region
                    }

                    module "ec2" {
                      source = "./modules/ec2"
                      version = "2.0.0"
                    }

                    provider "aws" {
                      region = var.region
                      version = "3.0.0"
                    }

                    terraform {
                      required_version = ">= 0.12"
                      required_providers {
                        gitlab = "~> 1.0"

                        aws = {
                          source = "hashicorp/aws"
                          version = "> 3.0.0"
                        }

                        google = {
                          version = ">= 4.28, < 6"
                          source = "hashicorp/google"
                        }
                      }
                      provider_meta "aws" {
                        build_tags = ["aws"]
                      }
                    }
                HCL
              )

